/* Decor: cut-out PNG stickers + emoji stickers + text on photos.
   Drives both the live viewfinder (DOM) and the captured photo / strip (Canvas). */
(function (global) {
  'use strict';

  const EMOJI_FONT = '"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';

  const CUTOUT_URLS = {
    s1: "data:image/png;base64,",
    s2: "data:image/png;base64,",
    s3: "data:image/png;base64,",
    s4: "data:image/png;base64,",
    s5: "data:image/png;base64,",
    s6: "data:image/png;base64,",
    s7: "data:image/png;base64,",
    s8: "data:image/png;base64,"
  };

  const CUTOUT_IMGS = {};
  Object.keys(CUTOUT_URLS).forEach(function (k) {
    const img = new Image();
    img.src = CUTOUT_URLS[k];
    CUTOUT_IMGS[k] = img;
  });

  // Items can be PNG cutouts ({ img: 's1'..'s8', x, y, s, r }) or emoji ({ e: '💗', x, y, s, r })
  const STICKERS = [
    { id: 'none', name: 'None', items: [] },
    {
      id: 'bubu_hug', name: '🐻 Hug & Heart', preview: 's8', items: [
        { img: 's8', x: 0.17, y: 0.82, s: 0.28, r: -8 },
        { img: 's7', x: 0.83, y: 0.16, s: 0.26, r: 10 },
        { e: '💗', x: 0.14, y: 0.14, s: 0.11, r: -12 }
      ]
    },
    {
      id: 'peach_goma', name: '🐱 Peach & Goma', preview: 's1', items: [
        { img: 's1', x: 0.18, y: 0.81, s: 0.28, r: -6 },
        { img: 's2', x: 0.82, y: 0.16, s: 0.26, r: 8 },
        { e: '💕', x: 0.85, y: 0.82, s: 0.12, r: 12 }
      ]
    },
    {
      id: 'cool_coffee', name: '😎 Cool Coffee', preview: 's6', items: [
        { img: 's6', x: 0.22, y: 0.84, s: 0.34, r: -5 },
        { img: 's3', x: 0.83, y: 0.18, s: 0.25, r: 9 },
        { e: '✨', x: 0.14, y: 0.14, s: 0.12, r: -10 }
      ]
    },
    {
      id: 'sweet_duo', name: '💖 Sweet Duo', preview: 's4', items: [
        { img: 's4', x: 0.21, y: 0.83, s: 0.32, r: -6 },
        { img: 's5', x: 0.86, y: 0.22, s: 0.20, r: 6 },
        { img: 's2', x: 0.16, y: 0.16, s: 0.24, r: -10 }
      ]
    },
    {
      id: 'all_cute', name: '✨ All Cute Pack', preview: 's7', items: [
        { img: 's1', x: 0.16, y: 0.16, s: 0.23, r: -10 },
        { img: 's4', x: 0.83, y: 0.16, s: 0.25, r: 8 },
        { img: 's8', x: 0.17, y: 0.83, s: 0.24, r: -6 },
        { img: 's6', x: 0.81, y: 0.84, s: 0.27, r: 7 }
      ]
    },
    {
      id: 'hearts', name: '💗 Hearts', items: [
        { e: '💗', x: 0.13, y: 0.11, s: 0.16, r: -14 },
        { e: '💖', x: 0.88, y: 0.2, s: 0.11, r: 12 },
        { e: '💕', x: 0.86, y: 0.78, s: 0.15, r: 10 },
        { e: '💗', x: 0.1, y: 0.7, s: 0.08, r: -8 }
      ]
    },
    {
      id: 'stars', name: '⭐ Stars', items: [
        { e: '⭐', x: 0.12, y: 0.12, s: 0.14, r: -10 },
        { e: '✨', x: 0.87, y: 0.16, s: 0.16, r: 8 },
        { e: '🌟', x: 0.88, y: 0.76, s: 0.13, r: 14 },
        { e: '✨', x: 0.12, y: 0.74, s: 0.1, r: -12 }
      ]
    },
    {
      id: 'bows', name: '🎀 Bows', items: [
        { e: '🎀', x: 0.14, y: 0.11, s: 0.18, r: -18 },
        { e: '🎀', x: 0.86, y: 0.78, s: 0.16, r: 16 },
        { e: '✨', x: 0.88, y: 0.15, s: 0.1, r: 0 }
      ]
    },
    {
      id: 'flowers', name: '🌸 Flowers', items: [
        { e: '🌸', x: 0.13, y: 0.12, s: 0.17, r: -12 },
        { e: '🌷', x: 0.87, y: 0.8, s: 0.15, r: 12 },
        { e: '🌼', x: 0.88, y: 0.17, s: 0.11, r: 20 },
        { e: '🌸', x: 0.1, y: 0.72, s: 0.09, r: 6 }
      ]
    }
  ];

  function get(id) {
    for (let i = 0; i < STICKERS.length; i++) if (STICKERS[i].id === id) return STICKERS[i];
    return STICKERS[0];
  }

  function buildStickers(container, id) {
    container.textContent = '';
    get(id).items.forEach(function (it) {
      if (it.img && CUTOUT_URLS[it.img]) {
        const im = document.createElement('img');
        im.className = 'vf-sticker-img';
        im.src = CUTOUT_URLS[it.img];
        im.alt = '';
        im.style.left = (it.x * 100) + '%';
        im.style.top = (it.y * 100) + '%';
        im.style.width = (it.s * 100) + '%';
        im.style.transform = 'translate(-50%, -50%) rotate(' + it.r + 'deg)';
        container.appendChild(im);
      } else {
        const s = document.createElement('span');
        s.textContent = it.e;
        s.style.left = (it.x * 100) + '%';
        s.style.top = (it.y * 100) + '%';
        s.style.fontSize = 'calc(var(--u) * ' + (it.s * 100) + ')';
        s.style.transform = 'translate(-50%, -50%) rotate(' + it.r + 'deg)';
        container.appendChild(s);
      }
    });
  }

  function buildText(el, text) { el.textContent = text || ''; }

  function drawCutoutAt(ctx, key, cx, cy, targetW, rotDeg) {
    const img = CUTOUT_IMGS[key];
    if (!img || !img.complete || !img.naturalWidth) return;
    const aspect = img.naturalHeight / img.naturalWidth;
    const dw = targetW;
    const dh = targetW * aspect;
    ctx.save();
    ctx.translate(cx, cy);
    if (rotDeg) ctx.rotate(rotDeg * Math.PI / 180);
    ctx.shadowColor = 'rgba(90, 47, 66, 0.22)';
    ctx.shadowBlur = targetW * 0.06;
    ctx.shadowOffsetY = targetW * 0.03;
    ctx.drawImage(img, -dw / 2, -dh / 2, dw, dh);
    ctx.restore();
  }

  function drawStickers(ctx, w, h, id) {
    get(id).items.forEach(function (it) {
      if (it.img) {
        drawCutoutAt(ctx, it.img, it.x * w, it.y * h, it.s * w, it.r);
      } else {
        ctx.save();
        ctx.translate(it.x * w, it.y * h);
        ctx.rotate(it.r * Math.PI / 180);
        ctx.font = Math.round(it.s * w) + 'px ' + EMOJI_FONT;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowColor = 'rgba(0,0,0,.18)';
        ctx.shadowBlur = w * 0.008;
        ctx.shadowOffsetY = w * 0.004;
        ctx.fillText(it.e, 0, 0);
        ctx.restore();
      }
    });
  }

  function drawText(ctx, w, h, text) {
    if (!text) return;
    const u = w / 100;
    ctx.save();
    ctx.font = '700 ' + (8.5 * u) + 'px "Caveat","Segoe Script",cursive';
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.shadowColor = 'rgba(0,0,0,.4)';
    ctx.shadowBlur = u * 1.5;
    ctx.shadowOffsetY = u * 0.5;
    ctx.fillText(text, w / 2, h * (1 - 0.035));
    ctx.restore();
  }

  function hydrateDOMStickers() {
    document.querySelectorAll("img[data-sticker]").forEach(function (el) {
      const k = el.getAttribute("data-sticker");
      if (k && CUTOUT_URLS[k]) el.src = CUTOUT_URLS[k];
    });
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", hydrateDOMStickers);
  } else {
    hydrateDOMStickers();
  }

  global.Decor = {
    stickers: STICKERS,
    cutoutUrls: CUTOUT_URLS,
    cutoutImgs: CUTOUT_IMGS,
    drawCutoutAt: drawCutoutAt,
    buildStickers: buildStickers,
    buildText: buildText,
    drawStickers: drawStickers,
    drawText: drawText
  };
})(window);
